const host=document.getElementById('replay-content');
const ZH=document.documentElement?.dataset?.lang==='zh',T=(en,zh)=>ZH?zh:en;
const reasonEn={'模型概率低于阈值':'Model probability below threshold','可见覆盖不足':'Fish not visible enough'},reason=r=>ZH?r:(reasonEn[r]||r);
const titles=ZH?{hunger:'饥饿驱动 H',stress:'紧张 S',exploration:'探索倾向 E',fatigue:'疲劳 F'}:{hunger:'Hunger drive H',stress:'Stress S',exploration:'Exploration E',fatigue:'Fatigue F'},modelNames=ZH?{logistic:'LR 逻辑回归',gam:'GAM 加性模型',hmm:'HMM 隐马尔可夫'}:{logistic:'LR · logistic regression',gam:'GAM · additive model',hmm:'HMM · hidden Markov model'};
const labelNames=ZH?{high:'高',low:'低',unknown:'无法判断'}:{high:'High',low:'Low',unknown:'Can\'t tell'};
const featureNames={speed_mean:['平均游速','体长/秒'],acceleration_mean:['平均加速度','体长/秒²'],displacement_ratio:['位移 / 路径',''],turn_rate:['转向率','弧度/秒'],feeding_zone_fraction:['投喂区占比','比例'],surface_fraction:['表层占比','比例'],dispersion:['群体分散',''],activity_fraction:['活动占比','比例'],wall_fraction:['靠壁占比','比例'],shelter_fraction:['可见遮蔽区占比','比例'],speed_baseline_z:['游速历史偏离',''],feeding_baseline_z:['投喂区历史偏离','']};
const featureNamesEn={speed_mean:['Mean speed','body lengths/s'],acceleration_mean:['Mean acceleration','body lengths/s²'],displacement_ratio:['Displacement / path',''],turn_rate:['Turn rate','rad/s'],feeding_zone_fraction:['Time in feeding area','share'],surface_fraction:['Time near surface','share'],dispersion:['Group spread',''],activity_fraction:['Active share','share'],wall_fraction:['Time by the glass','share'],shelter_fraction:['Time in visible shelter','share'],speed_baseline_z:['Speed vs. recent history',''],feeding_baseline_z:['Feeding area vs. recent history','']};
const pct=v=>Number.isFinite(v)?`${(v*100).toFixed(1)}%`:'—';
function element(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
try{
const response=await fetch('./assets/model-replay.json');if(!response.ok)throw Error('无法读取实验文件');const data=await response.json();if(data.domain!=='synthetic'||data.kind!=='held_out_single_fish_replay')throw Error('实验数据类型不符');
// Optional display filter for the project introduction; source data stays intact.
const requestedModels=(new URLSearchParams(location.search).get('models')||'').split(',').map(model=>model.trim());
const selectedModels=data.backends.filter(model=>requestedModels.includes(model));
const backends=selectedModels.length?selectedModels:data.backends;
host.innerHTML=`<div class="replay-toolbar"><label>${T('Test clip','测试场景')} <select id="replay-session" aria-label="${T('Replay clip','实验回放场景')}"></select></label><label>${T('State','状态维度')} <select id="replay-state" aria-label="${T('Replay state','实验回放状态维度')}"><option value="hunger">${titles.hunger}</option><option value="stress">${titles.stress}</option><option value="exploration">${titles.exploration}</option><option value="fatigue">${titles.fatigue}</option></select></label><output id="replay-time"></output></div><div class="replay-timeline"><button id="replay-prev" aria-label="${T('Previous window','上一时间窗')}">←</button><input id="replay-window" aria-label="${T('Replay window','实验回放时间窗')}" type="range" min="0" max="11" value="0" step="1"><button id="replay-next" aria-label="${T('Next window','下一时间窗')}">→</button></div><div class="replay-truth"><div><span>${T('Hidden truth for this window','窗口隐藏真值')}</span><strong id="replay-truth-value"></strong><small id="replay-truth-label"></small></div><p>${T('The truth value is the generator\'s average over the window. The models output the probability of the “high” class, so the two aren\'t the same kind of continuous score.','真值是生成器的窗口均值。模型输出的是“高类别”的概率，不能把二者当作同一种连续分数。')}</p></div><div id="replay-models" class="replay-models"></div><div id="replay-quality" class="replay-quality"></div><p id="replay-events" class="replay-events"></p><details class="replay-features"><summary>${T('See the 12 model inputs for this window','查看该窗口的 12 项模型输入')}</summary><div id="replay-features-grid"></div><p>${T('Missing values show as “missing”, not as normal. History-based deviations stay missing when there is too little history or too little variation.','缺失显示为“缺失”，不填成正常。短期历史不足或波动过小时，历史偏离保持缺失。')}</p></details><p class="replay-footnote">${T('Metrics come from the full independent test set; the probability threshold is 0.70. Windows with poor observation quality stay in the replay; the source evaluation files are the reference for metrics. All results only validate the synthetic experiment and are not psychological measurements of real fish.','指标来自完整独立测试集；概率门槛为 0.70。包括质量不足的窗口在回放中保留；评估指标以源评估文件为准。所有结果仅验证合成实验，不代表真实鱼心理测量。')}</p>`;
const get=id=>document.getElementById(id),select=get('replay-session'),slider=get('replay-window');data.sessions.forEach(s=>{const o=element('option','',`${s.id} · H${s.initial_state.hunger>=.5?T('↑','高'):T('↓','低')} S${s.initial_state.stress>=.5?T('↑','高'):T('↓','低')} E${s.initial_state.exploration>=.5?T('↑','高'):T('↓','低')} F${s.initial_state.fatigue>=.5?T('↑','高'):T('↓','低')}`);o.value=s.id;select.append(o);});select.value='test_12';
function render(){const session=data.sessions.find(s=>s.id===select.value),index=Number(slider.value),w=session.windows[index],state=get('replay-state').value,task='sim_'+state;slider.max=String(session.windows.length-1);get('replay-time').textContent=`${w.start_s.toFixed(0)}–${w.end_s.toFixed(0)} ${T('s','秒')} · ${index+1}/${session.windows.length}`;get('replay-prev').disabled=index===0;get('replay-next').disabled=index===session.windows.length-1;get('replay-truth-value').textContent=w.truth[state].toFixed(3);get('replay-truth-label').textContent=T(`${titles[state]}: ${w.truth[state]>=session.label_threshold?'high':'low'} (label threshold ${session.label_threshold})`,`${titles[state]}：${w.truth[state]>=session.label_threshold?'高':'低'}（标签阈值 ${session.label_threshold}）`);
const models=get('replay-models');models.style.setProperty('--replay-model-count',String(backends.length));models.replaceChildren();for(const backend of backends){const pred=w.predictions[backend][task],metrics=data.metrics[backend][task],card=element('article','replay-model');card.append(element('h3','',modelNames[backend]));if(!pred){card.append(element('p','',T('Not trained for this task','该任务未训练')));models.append(card);continue;}const verdict=element('span',`replay-verdict ${pred.label==='unknown'?'unknown':''}`,labelNames[pred.label]??pred.label);card.append(verdict,element('p','probability-caption',T('P(high class)','P（高类别）')),element('strong','probability-value',pct(pred.probabilities?.high)));const meter=element('meter','probability-meter');meter.min=0;meter.max=1;meter.hidden=!Number.isFinite(pred.probabilities?.high);meter.value=pred.probabilities?.high??0;meter.setAttribute('aria-label',T(`${modelNames[backend]}: probability of high ${titles[state]}`,`${modelNames[backend]}的${titles[state]}高类别概率`));card.append(meter,element('p','prediction-reason',pred.reason?reason(pred.reason):T('Observation quality and probability threshold passed','观测质量与概率门槛通过')));const stats=element('div','replay-stats');stats.append(element('span','',`${T('Test accuracy','测试准确率')} ${pct(metrics.accuracy)}`),element('span','',`${T('Coverage','接受率')} ${pct(metrics.accepted_fraction)}`));card.append(stats);models.append(card);}
get('replay-quality').textContent=w.quality_ok?T('Observation quality: passed','观测质量：通过'):`${T('Observation quality: insufficient','观测质量：不足')} · ${w.quality_reasons.map(reason).join(T('; ','；'))}`;get('replay-quality').classList.toggle('quality-warning',!w.quality_ok);
const eventNames=ZH?{food_offered:'投放食物',disturbance:'模拟惊扰',food_consumed:'模拟进食'}:{food_offered:'Food offered',disturbance:'Simulated disturbance',food_consumed:'Simulated meal'};const events=session.events.filter(e=>e.time_s>=w.start_s&&e.time_s<w.end_s);get('replay-events').textContent=events.length?T('Events in this window: ','本窗口事件：')+events.map(e=>`${e.time_s.toFixed(1)} ${T('s','秒')} ${eventNames[e.type]||e.type}`).join(' · '):T('No generator events in this window','本窗口无生成器事件');
const grid=get('replay-features-grid');grid.replaceChildren();for(const [key,[zhName,zhUnit]] of Object.entries(featureNames)){const [name,unit]=ZH?[zhName,zhUnit]:featureNamesEn[key],item=element('div','replay-feature'),v=w.features[key];item.append(element('span','',name),element('strong','',Number.isFinite(v)?(zhUnit==='比例'?pct(v):`${v.toFixed(3)}${unit?' '+unit:''}`):T('missing','缺失')));grid.append(item);}}
select.onchange=()=>{slider.value='0';render();};get('replay-state').onchange=render;slider.oninput=render;get('replay-prev').onclick=()=>{slider.value=String(Math.max(0,Number(slider.value)-1));render();};get('replay-next').onclick=()=>{slider.value=String(Math.min(Number(slider.max),Number(slider.value)+1));render();};render();host.setAttribute('aria-busy','false');
}catch(error){host.replaceChildren(element('p','replay-error',T('The experiment replay is unavailable. Open it through a local HTTP server and check that assets/model-replay.json exists.','实验回放暂不可用。请通过本地 HTTP 服务打开，并检查 assets/model-replay.json 是否存在。')));host.setAttribute('aria-busy','false');console.error('Replay data failed',error);}
